<template>
  <div>
    <!-- 作业表格 -->
    <h2>作业</h2>
    <div style="overflow-x: auto">
      <a-table
        :dataSource="homeworkSource"
        :columns="hwColumns"
        :pagination="{ pageSize: 5 }"
        rowKey="key"
        bordered
      >
        <template #bodyCell="{ text, record, column }">
          <template v-if="column.dataIndex === 'url'">
            <router-link
              :to="{ name: 'FileViewer', query: { url: record.url } }"
            >
              查看/下载
            </router-link>
          </template>
          <template v-else-if="column.dataIndex === 'description'">
            <a @click="showDescription(record)">查看详情</a>
          </template>
          <template v-else>
            {{ text }}
          </template>
        </template>
      </a-table>
    </div>

    <!-- 推荐阅读资料表格 -->
    <h2>推荐阅读资料</h2>
    <div style="overflow-x: auto">
      <a-table
        :dataSource="readingSource"
        :columns="readingColumns"
        :pagination="{ pageSize: 5 }"
        rowKey="key"
        bordered
      >
        <template #link="{ text }">
          <a :href="text" target="_blank">访问链接</a>
        </template>
      </a-table>
    </div>

    <!-- 描述详情的模态框 -->
    <a-modal
      v-model:visible="isDescriptionModalVisible"
      :title="currentItem.title"
      @cancel="handleDescriptionCancel"
      footer="null"
    >
      <p>{{ currentItem.description }}</p>
    </a-modal>
  </div>
</template>

<script setup>
import { ref } from "vue";

// 作业数据源
const homeworkSource = ref([
  {
    key: "1",
    title: "作业 1",
    deadline: "2023-10-20",
    url: "/homework/hw1.pdf",
    description: "作业 1 的详细描述内容。",
  },
  // ...existing homework data...
]);

// 作业表格的列定义
const hwColumns = [
  {
    title: "标题",
    dataIndex: "title",
    key: "title",
  },
  {
    title: "截止日期",
    dataIndex: "deadline",
    key: "deadline",
  },
  {
    title: "链接",
    dataIndex: "url",
    key: "url",
  },
  {
    title: "描述",
    dataIndex: "description",
    key: "description",
  },
];

// 推荐阅读资料数据
const readingSource = ref([
  {
    key: "1",
    title: "计算机网络: 自顶向下方法",
    isbn: "978-7-302-27258-3",
    publisher: "清华大学出版社",
    link: "https://example.com/book1",
  },
  // ...existing reading data...
]);

const readingColumns = [
  {
    title: "书名",
    dataIndex: "title",
    key: "title",
  },
  {
    title: "ISBN",
    dataIndex: "isbn",
    key: "isbn",
  },
  {
    title: "出版社",
    dataIndex: "publisher",
    key: "publisher",
  },
  {
    title: "访问链接",
    dataIndex: "link",
    key: "link",
    slots: { customRender: "link" },
  },
];

// 描述详情模态框的状态管理
const isDescriptionModalVisible = ref(false);
const currentItem = ref({
  key: "",
  title: "",
  description: "",
});

function showDescription(item) {
  currentItem.value = item;
  isDescriptionModalVisible.value = true;
}

function handleDescriptionCancel() {
  isDescriptionModalVisible.value = false;
}
</script>

<style scoped>
.ant-table {
  will-change: transform;
}
</style>
