<template>
  <div>
    <h2>课程项目</h2>
    
    <!-- 项目列表 -->
    <a-list
      v-if="!loading"
      :data-source="projects"
      :pagination="{
        pageSize: 5,
        total: projects.length,
        onChange: onPageChange
      }"
    >
      <template #renderItem="{ item }">
        <a-list-item>
          <a-card style="width: 100%">
            <template #title>
              <div class="project-header">
                <span>{{ item.title }}</span>
                <a-tag :color="getStatusColor(item.status)">
                  {{ item.status }}
                </a-tag>
              </div>
            </template>
            <template #extra>
              <a-space>
                <a-button @click="showProjectDetail(item)">查看详情</a-button>
                <a-button 
                  v-if="item.status !== '已截止'"
                  type="primary"
                  @click="showSubmissionGuide(item)"
                >
                  提交说明
                </a-button>
              </a-space>
            </template>
            <a-descriptions>
              <a-descriptions-item label="截止日期">
                {{ item.deadline }}
              </a-descriptions-item>
              <a-descriptions-item label="分值">
                {{ item.score }}分
              </a-descriptions-item>
            </a-descriptions>
            <p>{{ item.shortDescription }}</p>
          </a-card>
        </a-list-item>
      </template>
    </a-list>

    <!-- 项目详情模态框 -->
    <a-modal
      v-model:visible="isDetailVisible"
      :title="currentProject.title"
      width="800px"
      @cancel="handleCancel"
    >
      <a-descriptions>
        <a-descriptions-item label="截止日期">
          {{ currentProject.deadline }}
        </a-descriptions-item>
        <a-descriptions-item label="分值">
          {{ currentProject.score }}分
        </a-descriptions-item>
        <a-descriptions-item label="状态">
          <a-tag :color="getStatusColor(currentProject.status)">
            {{ currentProject.status }}
          </a-tag>
        </a-descriptions-item>
      </a-descriptions>
      <div class="project-content">
        <h3>项目要求</h3>
        <div v-html="currentProject.description"></div>
        
        <h3>提交记录</h3>
        <a-table
          :columns="submissionColumns"
          :data-source="currentProject.submissions"
          :pagination="false"
        >
          <template #bodyCell="{ column, record }">
            <template v-if="column.dataIndex === 'action'">
              <a-button type="link" @click="downloadFile(record)">
                下载
              </a-button>
            </template>
          </template>
        </a-table>
      </div>
    </a-modal>

    <!-- 提交说明模态框 -->
    <a-modal
      v-model:visible="isSubmissionGuideVisible"
      :title="'提交说明 - ' + currentProject.title"
      width="600px"
      @cancel="handleSubmissionGuideCancel"
    >
      <div class="submission-guide">
        <h3>提交要求</h3>
        <ul>
          <li>文件命名格式：学号_姓名_{{ currentProject.title }}.pdf</li>
          <li>文件大小：不超过10MB</li>
          <li>文件格式：PDF格式</li>
        </ul>

        <h3>提交方式</h3>
        <p>请将项目文件发送至以下邮箱：</p>
        <a-typography-paragraph copyable>ta_network@example.com</a-typography-paragraph>
        
        <h3>注意事项</h3>
        <ul>
          <li>邮件主题格式：计网课程项目提交_学号_姓名</li>
          <li>截止时间：{{ currentProject.deadline }}</li>
          <li>如有问题请联系助教：张助教（电话：123-4567-8900）</li>
        </ul>
      </div>
    </a-modal>
  </div>
</template>

<script setup>
import { ref } from 'vue';
// 页面加载状态
const loading = ref(false);

// 项目数据
const projects = ref([
  {
    id: 1,
    title: "计算机网络实验一：网络协议分析",
    shortDescription: "使用 Wireshark 进行网络协议分析，完成报告。",
    description: `
      <h4>实验目的：</h4>
      <p>1. 熟悉 Wireshark 的使用</p>
      <p>2. 了解网络协议的基本结构</p>
      <p>3. 掌握协议分析方法</p>
      
      <h4>实验要求：</h4>
      <p>1. 完成TCP协议分析</p>
      <p>2. 完成HTTP协议分析</p>
      <p>3. 提交详细的实验报告</p>
    `,
    deadline: "2023-12-01",
    score: 20,
    status: "进行中",
    submissions: [
      {
        id: 1,
        date: "2023-11-20",
        filename: "实验一报告.pdf",
        fileUrl: "/uploads/report1.pdf"
      }
    ]
  },
  // 可以添加更多项目...
]);

// 提交记录表格列定义
const submissionColumns = [
  {
    title: '提交时间',
    dataIndex: 'date',
    key: 'date',
  },
  {
    title: '文件名',
    dataIndex: 'filename',
    key: 'filename',
  },
  {
    title: '操作',
    dataIndex: 'action',
    key: 'action',
  },
];

// 状态管理
const isDetailVisible = ref(false);
const currentProject = ref({});
const currentPage = ref(1);

// 获取状态颜色
const getStatusColor = (status) => {
  switch (status) {
    case '已截止': return 'red';
    case '进行中': return 'green';
    default: return 'blue';
  }
};

// 页面切换
const onPageChange = (page) => {
  currentPage.value = page;
};

// 显示项目详情
const showProjectDetail = (project) => {
  currentProject.value = project;
  isDetailVisible.value = true;
};

// 关闭模态框
const handleCancel = () => {
  isDetailVisible.value = false;
};

// 添加提交说明模态框状态
const isSubmissionGuideVisible = ref(false);

// 显示提交说明
const showSubmissionGuide = (project) => {
  currentProject.value = project;
  isSubmissionGuideVisible.value = true;
};

// 关闭提交说明模态框
const handleSubmissionGuideCancel = () => {
  isSubmissionGuideVisible.value = false;
};

// 下载文件
const downloadFile = (record) => {
  window.open(record.fileUrl, '_blank');
};
</script>

