<template>
  <a-layout style="min-height: 100vh">
    <!-- 侧边栏 -->
    <a-layout-sider v-model:collapsed="collapsed" collapsible>
      <div class="logo" />
      <a-menu v-model:selectedKeys="selectedKeys" theme="dark" mode="inline">
        <!-- 使用 router-link 实现导航 -->
        <a-menu-item key="1">
          <router-link to="/">
            <HomeOutlined />
            <span>课程主页</span>
          </router-link>
        </a-menu-item>
        <!-- <a-menu-item key="2">
          <router-link to="/myinfo">
            <UserOutlined />
            <span>我的信息</span>
          </router-link>
        </a-menu-item> -->
        <a-menu-item key="2">
          <router-link to="/materials">
            <UserOutlined />
            <span>作业及资料</span>
          </router-link>
        </a-menu-item>
        <a-menu-item key="3">
          <router-link to="/projects">
            <FlagOutlined />
            <span>课程项目</span>
          </router-link>
        </a-menu-item>
        <a-menu-item key="4">
          <router-link to="/mindmap">
            <PieChartOutlined />
            <span>思维导图</span>
          </router-link>
        </a-menu-item>
      </a-menu>
    </a-layout-sider>

    <!-- 主布局 -->
    <a-layout>
      <a-layout-header style="background: #fff; padding: 0">
        <a-row justify="end">
          <!-- 使用一个a-col包含两个元素，内部再嵌套两个a-col进行细分 -->
          <a-col :xs="24" :sm="12" :md="6" :lg="5">
            <a-row align="middle" justify="end">
              <!-- 身份认证按钮，占一半的宽度 -->
              <!-- <a-col :span="12">
                <a-button @click="goToLogin" type="primary" style="width: 100%"
                  >身份认证</a-button
                >
              </a-col> -->
              <!-- 当前身份信息，占一半的宽度 -->
              <!-- <a-col :span="10" :offset="2">
                <span class="current-identity">{{ currentIdentity }}</span>
              </a-col> -->
            </a-row>
          </a-col>
        </a-row>
      </a-layout-header>

      <!-- 内容区域 -->
      <a-layout-content style="margin: 16px">
        <!-- 面包屑 -->
        <a-breadcrumb style="margin: 16px 0">
          <a-breadcrumb-item>课程网站</a-breadcrumb-item>
          <a-breadcrumb-item>{{ breadcrumbTitle }}</a-breadcrumb-item>
        </a-breadcrumb>
        <!-- 插槽，用于动态内容 -->
        <div
          :style="{ padding: '24px', background: '#fff', minHeight: '360px' }"
        >
          <slot>这里是页面内容</slot>
        </div>
      </a-layout-content>

      <!-- 页脚 -->
      <a-layout-footer style="text-align: center">
        Computer Networks 计算机网络（42034401）
      </a-layout-footer>
    </a-layout>
  </a-layout>
</template>

<script setup>
import { ref, watch } from "vue";
import { useRoute} from "vue-router";
import {
  HomeOutlined,
  UserOutlined,
  FlagOutlined,
  PieChartOutlined,
} from "@ant-design/icons-vue";

// 控制侧边栏收起状态
const collapsed = ref(false);
const selectedKeys = ref(["1"]);
const route = useRoute();
// const router = useRouter();

// 动态设置面包屑导航的标题
const breadcrumbTitle = ref("");
watch(
  () => route.path,
  (newPath) => {
    switch (newPath) {
      case "/":
        breadcrumbTitle.value = "课程主页";
        break;
      case "/materials":
        breadcrumbTitle.value = "作业及资料";
        break;
      case "/mindmap":
        breadcrumbTitle.value = "思维导图";
        break;
      case "/projects":
        breadcrumbTitle.value = "课程项目";
        break;
      default:
        breadcrumbTitle.value = "";
    }
  },
  { immediate: true }
);

// 处理身份认证逻辑，默认显示游客
// const currentIdentity = ref("游客");
// const goToLogin = () => {
//   if (currentIdentity.value === "游客") {
//     router.push("/login");
//   } else {
//     alert("已登录");
//   }
// };
</script>

<style scoped>
.logo {
  height: 32px;
  margin: 16px;
  background: rgba(255, 255, 255, 0.3);
}
