      <template #renderItem="{ item }">
        <a-list-item>
          <a-list-item-meta>
            <!-- 自定义头像部分 -->
            <template #avatar>
              <!-- 使用 Ant Design Vue 的通知图标 -->
              <NotificationTwoTone />
            </template>
            <!-- 自定义标题部分 -->
            <template #title>
              <span>{{ item.title }}</span>
            </template>
            <!-- 自定义描述部分 -->
            <template #description>
              <!-- 公告日期和查看详情链接 -->
              <div style="display: flex; justify-content: space-between">
                <span>{{ item.date }}</span>
