      <p>{{ currentNotice.content }}</p>
    </a-modal>

    <!-- 课件表格使用动态加载 -->
    <h2>课件</h2>
    <div style="overflow-x: auto">
      <a-table
        :data-source="currentSlides"
        :columns="slidesColumns"
        :pagination="{
          pageSize: 5,
          current: slidesPage,
          total: slidesSource.length,
          onChange: onSlidesPageChange
        }"
        :scroll="{ x: 1000, y: 400 }"
        :loading="tableLoading"
        rowKey="key"
        bordered
      >
        <!-- 使用 bodyCell 插槽自定义渲染 -->
        <template #bodyCell="{ text, record, column }">
          <template v-if="column.dataIndex === 'url'">
            <!-- 使用 router-link 跳转到新的路由，并传递文件路径 -->
            <router-link
              :to="{ name: 'FileViewer', query: { url: record.url } }"
            >
              查看/下载
            </router-link>
          </template>
          <template v-else-if="column.dataIndex === 'description'">
            <!-- 查看详情链接，点击后显示描述模态框 -->
