const loadData = async () => {
  try {
    loading.value = true;
    // 模拟API调用
    await new Promise(resolve => setTimeout(resolve, 1000));
    // 这里应该是实际的API调用
    loading.value = false;
  } catch (error) {
    console.error('Failed to load data:', error);
  }
};

// 公告页面切换处理
const onAnnouncementPageChange = (page) => {
  announcementPage.value = page;
};

// 课件页面切换处理
const onSlidesPageChange = (page) => {
  slidesPage.value = page;
  loadSlides();
};

// 异步加载表格数据
