  try {
    tableLoading.value = true;
    // 模拟API调用
    await new Promise(resolve => setTimeout(resolve, 500));
    // 这里应该是实际的API调用
  } catch (error) {
    console.error('Failed to load slides:', error);
  } finally {
    tableLoading.value = false;
  }
};

// 生命周期钩子
onMounted(async () => {
  try {
    loading.value = true;
    await Promise.all([
      loadData(),
      loadSlides()
    ]);
  } catch (error) {
    console.error('Failed to initialize data:', error);
