import { createRouter, createWebHashHistory } from "vue-router";
import CourseHome from "../views/CourseHome.vue";
import MyInfo from "../views/MyInfo.vue";
import FileViewer from "@/views/FileViewer.vue"; // 引入新的组件
import MindMap from "@/views/MindMap.vue";
import LoginPage from "@/views/LoginPage.vue";
import MaterialPage from "@/views/MaterialPage.vue";
import CourseProject from "@/views/CourseProject.vue";

const routes = [
  {
    path: "/",
    name: "CourseHome",
    component: CourseHome,
    meta: {
      layout: "default",
      title: "课程主页", // 设置页面标题
    }, // 使用通用布局
  },
  {
    path: "/myinfo",
    name: "MyInfo",
    component: MyInfo,
    meta: {
      layout: "default",
      title: "我的信息", // 设置页面标题
    }, // 使用通用布局
  },
  {
    // path: "/file-viewer",
    path: "/file-viewer",
    name: "FileViewer",
    component: FileViewer,
    meta: {
      layout: "empty",
      title: "文件查看", // 设置页面标题
    }, // 不使用通用布局
  },
  {
    path: "/mindmap",
    name: "MindMap",
    component: MindMap,
    meta: {
      layout: "default",
      title: "思维导图", // 设置页面标题
    },
  },
  {
    path: "/login",
    name: "LoginPage",
    component: LoginPage,
    meta: {
      layout: "empty",
      title: "登录", // 设置页面标题
    },
  },
  {
    path: "/materials",
    name: "MaterialPage",
    component: MaterialPage,
    meta: {
      layout: "default",
      title: "资料", // 设置页面标题
    }
  },
  {
    path: "/projects",
    name: "Projects",
    component: CourseProject,
    meta: {
      layout: "default",
      title: "项目", // 设置页面标题
    }
  }
];

const router = createRouter({
  history: createWebHashHistory(process.env.NODE_ENV === 'production' ? '/coursepage/' : '/'),
  routes,
});

// 添加全局导航守卫
router.beforeEach((to, from, next) => {
  if (to.matched.length === 0) {  // 如果没有匹配到路由
    next('/');  // 重定向到首页
  } else {
    next();
  }
});

export default router;
