<template>
  <div>
    <!-- 检查文件路径是否存在 -->
    <div v-if="!fileUrl">
      <p>未提供文件路径，请检查链接中的文件路径参数。</p>
    </div>

    <!-- 文件内容展示区域 -->
    <div v-else>
      <!-- 下载悬浮按钮 -->
      <a-float-button
        type="primary"
        :href="fileUrl"
        download
        :style="{
          right: '24px',
          bottom: '24px',
        }"
      >
        <template #icon>
          <DownloadOutlined />
        </template>
      </a-float-button>

      <!-- 根据文件类型渲染不同的组件 -->
      <div v-if="fileType === 'pdf'">
        <vue-office-pdf
          :src="fileUrl"
          style="width: 100%; height: 100vh"
          @error="handleError"
        />
      </div>

      <div v-else-if="fileType === 'docx'">
        <vue-office-docx
          :src="fileUrl"
          style="width: 100%; height: 100vh"
          @error="handleError"
        />
      </div>

      <div v-else-if="fileType === 'xlsx'">
        <vue-office-excel
          :src="fileUrl"
          style="width: 100%; height: 100vh"
          @error="handleError"
        />
      </div>

      <!-- 加载失败时显示的错误信息 -->
      <div v-if="hasError">
        <p>文件加载失败，请检查文件路径是否正确。</p>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed } from "vue";
import { useRoute } from "vue-router";
import { DownloadOutlined } from "@ant-design/icons-vue"; // 引入下载图标

//引入VueOfficePdf组件
import VueOfficePdf from "@vue-office/pdf";
//引入VueOfficeExcel组件
import VueOfficeExcel from "@vue-office/excel";
import VueOfficeDocx from "@vue-office/docx";
import "@vue-office/docx/lib/index.css";
//引入相关样式
import "@vue-office/excel/lib/index.css";

// 获取路由信息中的文件路径
const route = useRoute();
const fileUrl = route.query.url || ""; // 默认值为空字符串
const hasError = ref(false);

// 根据文件后缀名判断文件类型
const fileType = computed(() => {
  const extension = fileUrl.split(".").pop();
  if (["pdf"].includes(extension)) {
    return "pdf";
  } else if (["docx"].includes(extension)) {
    return "docx";
  } else if (["xlsx"].includes(extension)) {
    return "xlsx";
  } else {
    return "unknown";
  }
});

// 处理加载错误的情况
const handleError = () => {
  hasError.value = true;
};
</script>

<style scoped>
/* 如果需要自定义样式，可以在这里添加 */
</style>
