<template>
  <div id="app">
    <router-view v-slot="{ Component }">
      <!-- 判断是否需要使用通用布局 -->
      <component :is="getLayoutComponent">
        <component :is="Component"></component>
      </component>
    </router-view>
  </div>
</template>

<script setup>
import { useRoute } from "vue-router";
import { computed, watch } from "vue"; // 添加缺失的 computed 导入

// 引入通用布局组件
import DefaultLayout from "@/layouts/DefaultLayout.vue";
// App.vue
import EmptyLayout from "@/layouts/EmptyLayout.vue"; // 从文件导入

const route = useRoute();

watch(
  () => route.meta.layout,
  (newLayout, oldVal) => {
    console.log("layout 更新", newLayout, oldVal); // 检查 layout 是否更新
  }
);

// 根据路由的 meta.layout 属性，选择布局组件
const getLayoutComponent = computed(() => {
  const layout = route.meta.layout || "default";
  console.log("***** getLayoutComponent ****", route.meta, layout); // 输出 meta 信息，检查是否为 "empty"

  if (layout === "empty") {
    console.log("layout === empty");
    return EmptyLayout;
  }

  console.log("layout === default");
  return DefaultLayout; // 默认使用通用布局
});
</script>

<style>
/* 全局样式 */
</style>
