<template>
  <div>
    <a-row align="bottom" style="margin: 0 0 40px 0">
      <!-- 动态调整头像尺寸 -->
      <a-col :xs="10" :sm="8" :md="4">
        <a-avatar :size="avatarSize">
          <template #icon><UserOutlined /></template>
        </a-avatar>
      </a-col>

      <!-- 学号和姓名信息 -->
      <a-col :xs="12" :sm="8" :md="4">
        <div class="height-50">
          <p>学号：201801010101</p>
          <p>姓名：张三</p>
        </div>
      </a-col>

      <!-- 分数显示 -->
      <a-col :xs="24" :sm="12" :md="14" style="text-align: right">
        <h2>当前分数：{{ totalScore }}/100</h2>
      </a-col>
    </a-row>

    <!-- 待完成任务 -->
    <h2>待完成任务</h2>
    <div style="overflow-x: auto">
      <a-table
        :columns="waitColumns"
        :data-source="waitHw"
        rowKey="key"
        bordered
      >
        <!-- 自定义渲染 -->
        <template #bodyCell="{ text, record, column }">
          <template v-if="column.dataIndex === 'name'">
            <a :href="`/file-viewer?url=${record.name}`">{{ text }}</a>
          </template>
          <template v-else-if="column.dataIndex === 'submit'">
            <!-- 提交按钮 -->
            <a-button type="primary" @click="handleSubmit(record)">
              提交作业
            </a-button>
          </template>
          <template v-else>
            {{ text }}
          </template>
        </template>
      </a-table>
    </div>

    <!-- 已完成任务 -->
    <h2>已完成任务</h2>
    <div style="overflow-x: auto">
      <a-table
        :columns="doneColumns"
        :data-source="doneHw"
        rowKey="key"
        bordered
      >
        <!-- 自定义渲染 -->
        <template #bodyCell="{ text, record, column }">
          <template v-if="column.dataIndex === 'name'">
            <a :href="`/file-viewer?url=${record.name}`">{{ text }}</a>
          </template>
          <template v-else-if="column.dataIndex === 'submitTime'">
            {{ text }}
          </template>
          <template v-else-if="column.dataIndex === 'score'">
            {{ text }}
          </template>
          <template v-else-if="column.dataIndex === 'percentage'">
            {{ text }}
          </template>
          <template v-else-if="column.dataIndex === 'resubmit'">
            <!-- 重新提交按钮，判断是否在截止日期前 -->
            <a-button
              type="primary"
              @click="handleResubmit(record)"
              :disabled="isPastDeadline(record.deadline)"
            >
              重新提交
            </a-button>
          </template>
          <template v-else>
            {{ text }}
          </template>
        </template>
      </a-table>
    </div>

    <!-- 提交作业的对话框 -->
    <a-modal
      v-model:visible="isModalVisible"
      :title="modalTitle"
      @cancel="handleModalCancel"
      @ok="handleUpload"
    >
      <a-upload
        :beforeUpload="beforeUpload"
        :file-list="fileList"
        @remove="handleRemove"
        :maxCount="1"
      >
        <UploadOutlined />
        <a-button>选择文件</a-button>
      </a-upload>
    </a-modal>
  </div>
</template>

<script setup>
import { ref, computed } from "vue";
import { UserOutlined, UploadOutlined } from "@ant-design/icons-vue";
import moment from "moment"; // 引入 moment.js 用于日期处理

// 根据屏幕大小动态调整头像尺寸
const avatarSize = computed(() => {
  const width = window.innerWidth;
  if (width < 576) {
    // 手机端
    return 64;
  } else if (width < 768) {
    // 平板端
    return 96;
  } else {
    // 桌面端
    return 128;
  }
});

// 待完成任务的列定义
const waitColumns = [
  {
    title: "作业名称",
    dataIndex: "name",
    key: "name",
  },
  {
    title: "截止时间",
    dataIndex: "deadline",
    key: "deadline",
  },
  {
    title: "状态",
    dataIndex: "status",
    key: "status",
  },
  {
    title: "提交",
    dataIndex: "submit",
    key: "submit",
  },
];

// 已完成任务的列定义
const doneColumns = [
  {
    title: "作业名称",
    dataIndex: "name",
    key: "name",
  },
  {
    title: "截止时间",
    dataIndex: "deadline",
    key: "deadline",
  },
  {
    title: "提交时间",
    dataIndex: "submitTime",
    key: "submitTime",
  },
  {
    title: "得分",
    dataIndex: "score",
    key: "score",
  },
  {
    title: "占比",
    dataIndex: "percentage",
    key: "percentage",
  },
  {
    title: "重新提交",
    dataIndex: "resubmit",
    key: "resubmit",
  },
];

// 待完成任务的数据
const waitHw = ref([
  {
    key: "1",
    name: "作业1",
    deadline: "2023-10-15",
    status: "待完成",
  },
  {
    key: "2",
    name: "作业2",
    deadline: "2023-10-20",
    status: "待完成",
  },
]);

// 已完成任务的数据
const doneHw = ref([
  {
    key: "3",
    name: "作业3",
    deadline: "2023-10-10",
    submitTime: "2023-10-09 12:00",
    score: 80,
    percentage: 5,
  },
  {
    key: "4",
    name: "作业4",
    deadline: "2023-10-05",
    submitTime: "2023-10-04 12:00",
    score: 90,
    percentage: 10,
  },
  {
    key: "5",
    name: "作业5",
    deadline: "2023-10-08",
    submitTime: "2023-10-07 12:00",
    score: 70,
    percentage: 15,
  },
]);

// 计算当前总分
const totalScore = computed(() => {
  let total = 0;
  doneHw.value.forEach((hw) => {
    total += (hw.score * hw.percentage) / 100;
  });
  return total.toFixed(2);
});

// 控制提交作业的对话框
const isModalVisible = ref(false);
const modalTitle = ref("");
const currentHw = ref(null);
const fileList = ref([]);

// 点击“提交作业”按钮
function handleSubmit(record) {
  modalTitle.value = `提交作业：${record.name}`;
  currentHw.value = record;
  isModalVisible.value = true;
}

// 点击“重新提交”按钮
function handleResubmit(record) {
  modalTitle.value = `重新提交作业：${record.name}`;
  currentHw.value = record;
  isModalVisible.value = true;
}

// 关闭对话框
function handleModalCancel() {
  isModalVisible.value = false;
  fileList.value = [];
}

// 文件上传前的处理
function beforeUpload(file) {
  // 可以在这里添加文件类型和大小的校验
  fileList.value = [file];
  return false; // 阻止自动上传
}

// 移除已选择的文件
function handleRemove() {
  fileList.value = [];
}

// 点击“确定”按钮，上传文件
function handleUpload() {
  if (fileList.value.length === 0) {
    this.$message.error("请先选择文件！");
    return;
  }

  // 模拟上传文件到服务器
  // 这里需要调用后端 API，将文件和作业信息上传
  // 可以使用 axios 或其他 HTTP 客户端
  const formData = new FormData();
  formData.append("file", fileList.value[0]);
  formData.append("hwId", currentHw.value.key);
  formData.append("studentId", "201801010101");
  formData.append("submitTime", moment().format("YYYY-MM-DD HH:mm:ss"));

  // 假设上传成功，更新数据
  isModalVisible.value = false;
  fileList.value = [];

  // 更新待完成任务和已完成任务的数据
  // 这里需要根据实际情况更新，以下为模拟代码
  const hwIndex = waitHw.value.findIndex(
    (hw) => hw.key === currentHw.value.key
  );
  if (hwIndex !== -1) {
    const hw = waitHw.value.splice(hwIndex, 1)[0];
    hw.submitTime = formData.get("submitTime");
    hw.score = 0; // 等待老师评分
    hw.percentage = 5; // 假设占比 5%
    doneHw.value.push(hw);
  } else {
    // 重新提交的情况
    const doneHwIndex = doneHw.value.findIndex(
      (hw) => hw.key === currentHw.value.key
    );
    if (doneHwIndex !== -1) {
      doneHw.value[doneHwIndex].submitTime = formData.get("submitTime");
      // 覆盖之前的文件，等待老师重新评分
      doneHw.value[doneHwIndex].score = 0; // 重置得分
    }
  }

  this.$message.success("作业提交成功！");
}

// 判断是否过了截止日期
function isPastDeadline(deadline) {
  return moment().isAfter(moment(deadline, "YYYY-MM-DD"));
}
</script>

<style scoped>
/* 页面样式 */
</style>
